function validate([sequence, word]) {
  if (typeof sequence !== 'string' || sequence.length < 1 || sequence.length > 100) return 'sequence has 1 to 100 characters.';
  if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'word has 1 to 100 characters.';
  if (!/^[a-z]+$/.test(sequence) || !/^[a-z]+$/.test(word)) return 'Use only lowercase English letters.';
  return null;
}

