function maxRepeating(sequence, word) {
  const m = word.length;
  const fail = new Array(m).fill(0);
  let matched = 0;
  for (let i = 1; i < m; i++) {
    while (matched > 0 && word[i] !== word[matched]) {
      matched = fail[matched - 1];
    }
    if (word[i] === word[matched]) {
      matched++;
    }
    fail[i] = matched;
  }
  const run = new Array(sequence.length).fill(0);
  let best = 0;
  matched = 0;
  for (let i = 0; i < sequence.length; i++) {
    while (matched > 0 && sequence[i] !== word[matched]) {
      matched = fail[matched - 1];
    }
    if (sequence[i] === word[matched]) {
      matched++;
    }
    if (matched === m) {
      run[i] = i >= m ? run[i - m] + 1 : 1;
      best = Math.max(best, run[i]);
      matched = fail[m - 1];
    }
  }
  return best;
}

