function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 1 + pick(3));
  const randomText = length => Array.from({ length }, () => letters[pick(letters.length)]).join('');
  const word = randomText(size === 'large' && rand() < 0.2 ? 1 + pick(40) : 1 + pick(5));
  const length = size === 'large' ? 90 + pick(11) : 1 + pick(14);
  // Mix runs of copies, near-copies and noise so that overlapping and broken runs both appear.
  let sequence = rand() < 0.5 ? word.slice(pick(word.length)) : '';
  while (sequence.length < length) {
    const roll = rand();
    if (roll < 0.5) sequence += word.repeat(1 + pick(5));
    else if (roll < 0.7) sequence += word.slice(0, pick(word.length)) + randomText(1);
    else sequence += randomText(1 + pick(3));
  }
  return [sequence.slice(0, length), word];
}
